      record.requirement?.[key] !== undefined && record.requirement[key] === buyer?.requirement?.[key]) ||
    !['network','transaction','success'].every(key =>
      record.receipt?.[key] !== undefined && record.receipt[key] === buyer?.receipt?.[key]) ||
