  if (x.limit !== undefined) need(Number.isInteger(x.limit) && x.limit >= 1 && x.limit <= 100, 'INVALID_LIMIT');
  if (x.offset !== undefined) need(Number.isSafeInteger(x.offset) && x.offset >= 0, 'INVALID_OFFSET');
