  if (x.bodyFile !== undefined) {
    abs(x.bodyFile, 'BODY_PATH_MUST_BE_ABSOLUTE');
    need(!['GET','HEAD'].includes(method), 'BODY_DISALLOWED_FOR_METHOD');
