      need(flags.workspace&&flags['approved-request'],'DATASET_LOST_OUTPUT_ORIGINAL_INPUTS_REQUIRED');
    if(command==='recover-lost-output')
      need(/^[a-f0-9]{64}$/.test(flags.transaction??'')&&/^[a-f0-9]{64}$/.test(flags['request-sha']??''),
