const WORKER=fileURLToPath(new URL('./dataset-session-portable.py',import.meta.url));
const SCHEMA='stellar-forge.sf88.dataset-session-archive.v1';
const MAX_JSON=32*1024*1024;
const HASH=/^[a-f0-9]{64}$/;
