  operation:operationId,...settings}={}) {
  need(exact(directory)&&exact(archive),'DATASET_ARCHIVE_ABSOLUTE_PATH_REQUIRED');
  need(HASH.test(expectedSha256??''),'DATASET_ARCHIVE_EXACT_SOURCE_REQUIRED');
