    need(workspace === undefined || typeof workspace === 'string' && isAbsolute(workspace) &&
      resolve(workspace) === workspace, 'DATASET_ABSOLUTE_WORKSPACE_REQUIRED');
    need(workspace === undefined || definition.workspaceDirectory === undefined ||
