  return new Promise((resolve,reject)=>{
    const child=spawn(cfg.operator.python,['-I','-B','-u',WORKER,
      '--config',datasetStoragePath(configurationPath),'--sha256',configurationSha256],
      {env,shell:false,stdio:['ignore','pipe','ignore']});
