export async function exportLostOutputProof({output,...options}={}) {
  const view=await readLostOutputRecovery(options);
  need(view,'LOST_OUTPUT_RECOVERY_NOT_COMPLETED');
  const facts=view.result.verifiedFacts;
  need(facts?.intentId===options.intentId&&facts.transaction===view.transaction&&
    facts.request_sha256===view.requestSha256&&HASH.test(view.sourceSha256??''),
    'LOST_OUTPUT_VERIFIED_FACTS_BINDING_MISMATCH');
  const queue=await openQueue(options.root),job=await queue.show(options.intentId);
  const completion=await privateFile(join(queue.root,'jobs',job.id,'lost-output','recovery.json'));
  need(output!==job.evidencePath,'LOST_OUTPUT_EXPORT_REQUIRES_DISTINCT_DESTINATION');
  await privateDirectory(dirname(output));
  const proof={schema:'stellar-forge.sf88.lost-output-verified-transfer.v1',
    origin:'ORIGINAL_SF43_VERIFIED_TRANSFER_RECOVERY',proof:'RPC_TX_AND_SEP41_TRANSFER_EVENT_MATCH',
    reservation:'ORIGINAL_SF36_FINALIZED',sellerReport:'LOCAL_OUTPUT_LOST_AFTER_PAYMENT',
    intentId:options.intentId,attemptId:view.attemptId,configSha256:view.configSha256,
    requestSha256:view.requestSha256,transaction:facts.transaction,network:facts.network,
    asset:facts.asset,payer:facts.payer,recipient:facts.recipient,atomicAmount:facts.atomicAmount,
    ledger:facts.ledger,matchingEventId:facts.eventId,transactionCreatedAt:facts.transactionCreatedAt,
    attemptStartedAt:view.attemptStartedAt,
    observedAt:view.observedAt,completedAt:view.completedAt,sealedRecoverySha256:sha(completion.raw),
    sourceHashes:view.sourceHashes,evidenceState:view.evidenceState,recordAuthority:view.recordAuthority};
  const stored=await createSelection(output,proof);
  need(same(stored,proof),'LOST_OUTPUT_EXPORTED_PROOF_CONFLICT');
  const exact=await privateFile(output);
  return {path:output,bytes:exact.raw.length,sha256:sha(exact.raw),proof};
}

/** Read original history with authenticated completed recoveries for this
 * accounting workspace. A damaged recovery stays visible as a local error. */
export async function readLostOutputQueueViews({root,workspace,...options}={}) {
  const queue=await openQueue(root),jobs=await queue.list();
  if(workspace===undefined)return jobs;
  const views=[];
  for(const job of jobs){
    try{
      const recovered=await readLostOutputRecovery({...options,root:queue.root,
        workspace,intentId:job.intentId??job.operation?.intentId});
      views.push(recovered?{...job,lostOutputFinalization:recovered}:job);
    }catch(error){
      const reason=/^[A-Z0-9_]{1,120}$/.test(error?.code??'')?error.code:'LOST_OUTPUT_HISTORY_READ_FAILED';
      views.push({...job,lostOutputFinalizationError:reason});
    }
  }
  return views;
}

// MIT. Explicit recovery of one original payment whose seller receipt was lost.
import {createHash, randomUUID} from 'node:crypto';
import {constants} from 'node:fs';
import {lstat, mkdir, open, realpath, link, unlink} from 'node:fs/promises';
import {dirname, isAbsolute, join, resolve} from 'node:path';
import {config, execution, need} from './config.mjs';
import {openQueue} from './queue.mjs';
import {openWorkspace} from './workspace.mjs';
import {runOriginalFinalityWorker} from './finalization.mjs';
import {resolveBuyerProxy} from '../sf31-buyer-client/public-transport.mjs';
import {resolveRpcEndpoint} from '../sf86-rpc-transfer-reconcile/terms.mjs';

const SOURCE='stellar-forge.sf88.missing-receipt-source.v1';
const VIEW='stellar-forge.sf88.manual-finalization.v1';
const HASH=/^[a-f0-9]{64}$/;
const FINALIZED=new Set(['FINALIZED','IDEMPOTENT_FINALIZED']);
const sha=value=>createHash('sha256').update(value).digest('hex');
const same=(left,right)=>JSON.stringify(left)===JSON.stringify(right);
const ownPrivate=info=>(info.mode&0o077)===0&&info.uid===process.getuid();
const safeReason=result=>/^[A-Z0-9_]{1,120}$/.test(result?.reason??'')?result.reason:'MANUAL_FINALITY_NOT_VERIFIED';

async function privateDirectory(path) {
  need(typeof path==='string'&&isAbsolute(path)&&resolve(path)===path,'MANUAL_ABSOLUTE_PATH_REQUIRED');
  const info=await lstat(path);
  need(info.isDirectory()&&!info.isSymbolicLink()&&ownPrivate(info)&&await realpath(path)===path,
    'MANUAL_PRIVATE_DIRECTORY_REQUIRED');
}
async function privateFile(path,limit=4_000_000) {
  await privateDirectory(dirname(path));
  const handle=await open(path,constants.O_RDONLY|constants.O_NOFOLLOW);
  try {
    const info=await handle.stat();
    need(info.isFile()&&ownPrivate(info)&&info.size<=limit,'MANUAL_PRIVATE_SOURCE_REQUIRED');
    const raw=await handle.readFile();
    need(raw.length<=limit,'MANUAL_SOURCE_TOO_LARGE');
    return {raw,value:JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(raw))};
  } finally {await handle.close();}
}
async function exists(path) {
  try {await lstat(path);return true;}catch(error){if(error.code==='ENOENT')return false;throw error;}
}
async function createSelection(path,value) {
  const temporary=join(dirname(path),'.selection-'+randomUUID());
  const file=await open(temporary,constants.O_WRONLY|constants.O_CREAT|constants.O_EXCL,0o600);
  try {
    try {await file.writeFile(JSON.stringify(value,null,2)+'\n');await file.sync();}
    finally {await file.close();}
    try {await link(temporary,path);}catch(error){if(error.code!=='EEXIST')throw error;}
    const parent=await open(dirname(path),constants.O_RDONLY);
    try {await parent.sync();}finally{await parent.close();}
  } finally {await unlink(temporary).catch(()=>{});}
  return (await privateFile(path)).value;
}
function expectedSelection(snapshot,{expectedRequestSha256,expectedAttemptId,expectedConfigSha256}={}) {
  for(const [selected,current] of [[expectedRequestSha256,snapshot.expectedRequestSha256],
    [expectedAttemptId,snapshot.attemptId],[expectedConfigSha256,snapshot.configSha256]])
    need(selected===undefined||typeof selected==='string'&&selected===current,'MANUAL_SELECTED_ATTEMPT_CHANGED');
}

async function originalContext({root,intentId,workspace,...expected}) {
  const queue=await openQueue(root);
  const job=await queue.show(intentId);
  need(job.attempt?.kind==='EXECUTE','INBOX_EXECUTION_ATTEMPT_REQUIRED');
  const jobDirectory=join(queue.root,'jobs',job.id);
  const active=await openWorkspace(['--dir',workspace]);
  const paths={request:join(jobDirectory,'request.json'),sourceConfig:join(jobDirectory,'source-config.json'),
    configuration:join(jobDirectory,'execution.json'),attempt:join(jobDirectory,'attempt.json'),
    evidence:join(active.manifest.directory,'evidence',job.id+'.json'),
    workspaceConfig:active.configPath,workspaceManifest:join(active.manifest.directory,'workspace.json')};
  need(job.evidencePath===paths.evidence,'MANUAL_EVIDENCE_PATH_MISMATCH');
  const sources=Object.fromEntries(await Promise.all(Object.entries(paths).map(async([name,path])=>
    [name,await privateFile(path)])));
  const cfg=await config(paths.configuration);
  const {op,owner,transport}=execution(cfg);
  const current=execution(active.config);
  need(sha(sources.configuration.raw)===job.configSha256&&
    ['python','actor','service','policy','ledger'].every(key=>owner[key]===current.owner[key])&&
    cfg.signerModule===active.config.signerModule&&cfg.evidenceDir===active.config.evidenceDir&&
    cfg.trustedPayer===active.config.trustedPayer&&same(transport,current.transport),
    'MANUAL_ORIGINAL_WORKSPACE_MISMATCH');
  need(['scheme','network','asset','payTo'].every(key=>op.expect[key]===current.op.expect[key]),
    'MANUAL_ORIGINAL_TERMS_MISMATCH');
  const evidence=sources.evidence.value;
  const reservation=evidence.operatorReservation;
  need(evidence.schema==='scf82.checkout-evidence.v1'&&evidence.intentId===intentId&&
    evidence.observation?.intentId===intentId&&reservation?.outcome==='FRESH_RESERVATION_APPROVED'&&
    reservation.requestId===intentId&&HASH.test(reservation.requestSha256??'')&&
    Number.isSafeInteger(evidence.report?.counts?.signedAttempts)&&evidence.report.counts.signedAttempts>=1,
    'MANUAL_ORIGINAL_RESERVATION_REQUIRED');
  need(evidence.observation?.buyer?.receipt==null&&evidence.reconciliation?.record?.receipt==null,
    'ORIGINAL_RECEIPT_PRESENT_USE_NORMAL_FINALIZER');
  need(Number.isFinite(Date.parse(evidence.observedAt))&&
    Date.parse(evidence.observedAt)>=Date.parse(job.attempt.startedAt),'MANUAL_EVIDENCE_PREDATES_ATTEMPT');
  need(op.expect.scheme==='exact'&&['network','asset'].every(key=>reservation[key]===op.expect[key])&&
    /^[1-9][0-9]*$/.test(reservation.reservedAtomicUnits??'')&&
    BigInt(reservation.reservedAtomicUnits)<=BigInt(op.expect.maxAtomic),'MANUAL_RESERVATION_TERMS_MISMATCH');
  const sourceHashes=Object.fromEntries(Object.entries(sources).map(([name,{raw}])=>[name,sha(raw)]));
  sourceHashes.body=job.bodySha256;
  const snapshot={schema:'stellar-forge.sf88.missing-receipt-attempt.v1',queueRoot:queue.root,
    workspace:active.manifest.directory,intentId,attemptId:job.attempt.id,configSha256:job.configSha256,
    expectedRequestSha256:reservation.requestSha256,attemptStartedAt:job.attempt.startedAt,
    evidenceObservedAt:evidence.observedAt,sourceHashes,bodySha256:job.bodySha256,bodyBytes:job.bodyBytes,
    expected:{network:op.expect.network,asset:op.expect.asset,amount:reservation.reservedAtomicUnits,
      payTo:op.expect.payTo,payer:cfg.trustedPayer}};
  expectedSelection(snapshot,expected);
  return {queue,job,jobDirectory,active,cfg,owner,transport,snapshot};
}

/** Read the retained original reservation metadata and frozen request. This
 * projection does not open keys, load a signer, contact a provider, or reserve. */
export async function inspectMissingReceiptAttempt(options={}) {
  return (await originalContext(options)).snapshot;
}

function recoveryView(result,snapshot) {
  const recovery=result.recovery;
  const binding=recovery?.binding;
  need(FINALIZED.has(result.outcome)&&recovery?.schema==='stellar-forge.sf36.manual-recovery.v1'&&
    binding?.intentId===snapshot.intentId&&binding.attemptId===snapshot.attemptId&&
    binding.configSha256===snapshot.configSha256&&binding.requestSha256===snapshot.expectedRequestSha256&&
    Object.keys(snapshot.sourceHashes).every(key=>binding.sourceHashes?.[key]===snapshot.sourceHashes[key]),
    'MANUAL_FINALITY_RESULT_BINDING_MISMATCH');
  return {schema:VIEW,intentId:binding.intentId,attemptId:binding.attemptId,configSha256:binding.configSha256,
    requestSha256:binding.requestSha256,transaction:binding.transaction,sourceHashes:binding.sourceHashes,
    sourcePath:binding.sourcePath,sourceSha256:binding.sourceSha256,workspace:binding.workspace,
    attemptStartedAt:binding.attemptStartedAt,evidenceObservedAt:binding.evidenceObservedAt,
    completedAt:recovery.completedAt,observedAt:recovery.observedAt,requestBinding:binding.requestBinding,
    association:'OPERATOR_SELECTED_TRANSACTION',result:{...recovery.result,outcome:result.outcome},
    recordAuthority:recovery.recordAuthority};
}
async function invoke(context,sourcePath,{signal,node=process.execPath,environment=process.env,verifyOnly=false}={}) {
  const {active,cfg,owner,transport,snapshot}=context;
  const privileged=await openWorkspace(['--dir',active.manifest.directory],{accounting:true,environment});
  need(same(privileged.config,active.config)&&same(privileged.manifest,active.manifest),'MANUAL_WORKSPACE_CHANGED');
  const directory=dirname(sourcePath);
  const reports=verifyOnly?directory:join(directory,'reports');
  if(!verifyOnly)await mkdir(reports,{mode:0o700}).catch(error=>{if(error.code!=='EEXIST')throw error;});
  await privateDirectory(reports);
  let rpcProxyUrl;
  if(!verifyOnly&&transport!==null) {
    resolveBuyerProxy(transport,environment);
    rpcProxyUrl=new URL(transport.proxyEnv===undefined?transport.proxyUrl:environment[transport.proxyEnv]).origin;
  }
  const args=['--manual-source',sourcePath,'--ledger',owner.ledger,'--policy',owner.policy,
    '--payer',cfg.trustedPayer,'--node',node,'--reports',reports,
    '--expected-request-sha',snapshot.expectedRequestSha256,
    ...(verifyOnly?['--verify-only']:['--rpc-endpoint',resolveRpcEndpoint(snapshot.expected.network,active.manifest.signer.rpcUrl)]),
    ...(rpcProxyUrl===undefined?[]:['--rpc-proxy-env','SF36_RPC_PROXY_URL'])];
  const result=await runOriginalFinalityWorker(owner.python,args,privileged.operatorEnvironment,signal,rpcProxyUrl,environment);
  need(FINALIZED.has(result.outcome),safeReason(result));
  return recoveryView(result,snapshot);
}

/** Authenticate an existing successful recovery against current original source
 * and SF36's HMAC journal. Returns null before a completed recovery. Provider IO
 * and ledger finalization are absent from this read path. */
export async function readMissingReceiptRecovery(options={}) {
  const queue=await openQueue(options.root);
  const job=await queue.show(options.intentId);
  const directory=join(queue.root,'jobs',job.id,'manual-finality');
  if(!await exists(join(directory,'recovery.json')))return null;
  const context=await originalContext(options);
  const envelope=(await privateFile(join(directory,'recovery.json'))).value;
  // The outer read selects only this job's fixed transaction descriptor. The
  // worker authenticates the HMAC, every binding and its original ledger row.
  const transaction=envelope.payload?.binding?.transaction;
  need(HASH.test(transaction??''),'MANUAL_RECOVERY_RECORD_INVALID');
  return invoke(context,join(directory,transaction+'.source.json'),{...options,verifyOnly:true});
}

/** Operator-selected finality for a recorded original attempt, without another
 * signer/payment. The original worker independently verifies the transfer and
 * atomically finalizes its existing reservation. All records are create-only. */
export async function recoverMissingReceipt(options={}) {
  const {transaction,expectedRequestSha256}=options;
  need(HASH.test(transaction??'')&&HASH.test(expectedRequestSha256??''),
    'MANUAL_TRANSACTION_AND_DIGEST_REQUIRED');
  const context=await originalContext(options);
  const {snapshot,jobDirectory}=context;
  const directory=join(jobDirectory,'manual-finality');
  await mkdir(directory,{mode:0o700}).catch(error=>{if(error.code!=='EEXIST')throw error;});
  await privateDirectory(directory);
  const selection={schema:SOURCE,queueRoot:snapshot.queueRoot,workspace:snapshot.workspace,
    intentId:snapshot.intentId,attemptId:snapshot.attemptId,configSha256:snapshot.configSha256,
    requestSha256:snapshot.expectedRequestSha256,transaction,sourceHashes:snapshot.sourceHashes};
  const sourcePath=join(directory,transaction+'.source.json');
  const source=await createSelection(sourcePath,selection);
  need(same(source,selection),'MANUAL_SELECTION_CONFLICT');
  const manualFinalization=await invoke(context,sourcePath,options);
  return {...await context.queue.show(options.intentId),manualFinalization};
}

// MIT. SF88 adapter to the original x402 SDK. SF81 owns approval/reservation.
import { isDeepStrictEqual } from 'node:util';
import { readFile, lstat } from 'node:fs/promises';
import { createRequire } from 'node:module';
import { dirname, isAbsolute, join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { createNativeBuyerSigner, readNativeSigningDiagnostic } from '../sf103-native-buyer-signer/adapter.mjs';
import { NETWORKS } from '../sf86-rpc-transfer-reconcile/terms.mjs';

const NETWORK = 'stellar:testnet';
const SDK_VERSION = '2.28.0';
const require = createRequire(import.meta.url);
const I128_MAX = 170141183460469231731687303715884105727n;
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const same = (left, right) => isDeepStrictEqual(left, right);
let sdkPromise;

export class NativeSignerError extends Error {
  constructor(code, nativeSigning) {
    super(code); this.name = 'NativeSignerError'; this.code = code;
    const diagnostic=readNativeSigningDiagnostic(nativeSigning);
    if(diagnostic)this.nativeSigning=diagnostic;
    // The adapter returns before SF31 constructs or sends its paid HTTP retry.
    this.paymentSent = false;
  }
}
const fail = code => { throw new NativeSignerError(code); };

function atomic(value) {
  if (typeof value !== 'string' || value.length > 39 || !/^[1-9][0-9]*$/.test(value))
    fail('SIGNER_INVALID_ATOMIC_AMOUNT');
  const amount = BigInt(value);
  if (amount > I128_MAX) fail('SIGNER_INVALID_ATOMIC_AMOUNT');
  return amount;
}

function pins(options) {
  if (!object(options) || !Object.hasOwn(NETWORKS, options.network)) fail('SIGNER_STELLAR_NETWORK_REQUIRED');
  if (typeof options.asset !== 'string' || !/^C[A-Z2-7]{55}$/.test(options.asset))
    fail('SIGNER_INVALID_ASSET');
  if (typeof options.payTo !== 'string' || !/^[GC][A-Z2-7]{55}$/.test(options.payTo))
    fail('SIGNER_INVALID_RECIPIENT');
  if (typeof options.expectedPayer !== 'string' || !/^[GC][A-Z2-7]{55}$/.test(options.expectedPayer))
    fail('SIGNER_EXPECTED_PAYER_REQUIRED');
  atomic(options.maxAtomic);
  const paymentFlow = options.paymentFlow === undefined ? 'authorization' : options.paymentFlow;
  if (!['authorization','upfront'].includes(paymentFlow)) fail('SIGNER_UNSUPPORTED_PAYMENT_FLOW');
  let rpc;
  try { rpc = new URL(options.rpcUrl ?? NETWORKS[options.network].defaultRpc); }
  catch { fail('SIGNER_RPC_URL_INVALID'); }
  if (rpc.protocol !== 'https:' || rpc.username || rpc.password || rpc.search || rpc.hash)
    fail('SIGNER_RPC_HTTPS_REQUIRED');
  if (Object.entries(NETWORKS).some(([network, profile]) => network !== options.network &&
      profile.rpcEndpoints.some(endpoint => new URL(endpoint).href === rpc.href)))
    fail('SIGNER_RPC_NETWORK_MISMATCH');
  return Object.freeze({ network: options.network, asset: options.asset, payTo: options.payTo,
    maxAtomic: options.maxAtomic, expectedPayer: options.expectedPayer, rpcUrl:rpc.href, paymentFlow });
}

export function validateNativeSignerConfiguration(options) { return pins(options); }

/** Validate the original SF31 payload against independent operator configuration. */
export function validateNativeSignerInput(payload, configuration) {
  const policy = pins(configuration);
  const { intent, challenge, accepted } = payload ?? {};
  if (!object(intent) || !object(challenge) || !object(accepted) ||
      challenge.x402Version !== 2 || !object(challenge.resource) ||
      !Array.isArray(challenge.accepts) || challenge.accepts.length < 1 || challenge.accepts.length > 32)
    fail('SIGNER_INVALID_CHALLENGE');
  if (accepted.scheme !== 'exact' || accepted.network !== policy.network ||
      accepted.asset !== policy.asset || accepted.payTo !== policy.payTo)
    fail('SIGNER_PAYMENT_TERMS_CHANGED');
  if (atomic(accepted.amount) > atomic(policy.maxAtomic) ||
      atomic(intent.maxAtomic) > atomic(policy.maxAtomic) ||
      atomic(accepted.amount) > atomic(intent.maxAtomic)) fail('SIGNER_SPEND_CAP_EXCEEDED');
  if (!Number.isSafeInteger(accepted.maxTimeoutSeconds) || accepted.maxTimeoutSeconds < 1 ||
      accepted.maxTimeoutSeconds > 86400 || accepted.extra?.areFeesSponsored !== true ||
      (accepted.extra?.paymentFlow === undefined ? 'authorization' : accepted.extra.paymentFlow) !== policy.paymentFlow)
    fail('SIGNER_UNSUPPORTED_STELLAR_TERMS');
  if (!same(intent.acceptedTerms, accepted) ||
      ['scheme', 'network', 'asset', 'payTo', 'amount', 'maxTimeoutSeconds'].some(key => intent[key] !== accepted[key]))
    fail('SIGNER_APPROVED_INTENT_MISMATCH');
  if (typeof intent.intentId !== 'string' || !/^[A-Za-z0-9._:-]{1,160}$/.test(intent.intentId) ||
      !['GET', 'HEAD', 'POST', 'PUT', 'PATCH', 'DELETE'].includes(intent.method) ||
      typeof intent.url !== 'string' || challenge.resource.url !== intent.url)
    fail('SIGNER_RESOURCE_MISMATCH');
  let url;
  try { url = new URL(intent.url); } catch { fail('SIGNER_RESOURCE_MISMATCH'); }
  if (url.protocol !== 'https:' || url.username || url.password || url.hash || url.href !== intent.url)
    fail('SIGNER_RESOURCE_MISMATCH');
  if (challenge.accepts.filter(option => same(option, accepted)).length !== 1)
    fail('SIGNER_ACCEPTED_OPTION_MISMATCH');
  if (challenge.extensions !== undefined && !object(challenge.extensions))
    fail('SIGNER_INVALID_CHALLENGE');
  // Snapshots survive asynchronous SDK/RPC work. Caller changes cannot alter a signed quote.
  return { policy, intent: structuredClone(intent), accepted: structuredClone(accepted),
    challenge: structuredClone(challenge) };
}

async function packageVersion(name, specifier) {
  let directory;
  try { directory = dirname(require.resolve(specifier)); }
  catch { fail('OFFICIAL_STELLAR_SDK_UNAVAILABLE'); }
  for (;;) {
    try {
      const manifest = JSON.parse(await readFile(join(directory, 'package.json'), 'utf8'));
      if (manifest.name === name) return manifest.version;
    } catch (error) {
      if (error.code !== 'ENOENT') fail('OFFICIAL_STELLAR_SDK_METADATA_INVALID');
    }
    const parent = dirname(directory);
    if (parent === directory) fail('OFFICIAL_STELLAR_SDK_METADATA_INVALID');
    directory = parent;
  }
}

async function officialSdk() {
  sdkPromise ??= (async () => {
    const versions = {
      core:await packageVersion('@x402/core', '@x402/core/client'),
      stellar:await packageVersion('@x402/stellar', '@x402/stellar/exact/client'),
    };
    if (!Object.values(versions).every(version => version === SDK_VERSION))
      fail('OFFICIAL_STELLAR_SDK_VERSION_MISMATCH');
    const [core, stellar, signer] = await Promise.all([
    import('@x402/core/client'), import('@x402/stellar/exact/client'), import('@x402/stellar'),
    ]);
    if (typeof core.x402Client !== 'function' || typeof core.x402Client.prototype.setSpendControls !== 'function' ||
        typeof stellar.ExactStellarScheme !== 'function' || typeof signer.createEd25519Signer !== 'function')
      fail('OFFICIAL_STELLAR_SDK_INCOMPATIBLE');
    return { x402Client: core.x402Client, ExactStellarScheme: stellar.ExactStellarScheme,
      createEd25519Signer: signer.createEd25519Signer, versions };
  })().catch(error => {
    sdkPromise = undefined;
    if (error instanceof NativeSignerError) throw error;
    fail('OFFICIAL_STELLAR_SDK_UNAVAILABLE');
  });
  return sdkPromise;
}

/** Package availability only: no provider import, key access, RPC or signature. */
export async function inspectNativeSignerRuntime(network = NETWORK) {
  if (!Object.hasOwn(NETWORKS, network)) fail('SIGNER_STELLAR_NETWORK_REQUIRED');
  const sdk = await officialSdk();
  return { sdkVersion:SDK_VERSION, versions:sdk.versions, network, networks:Object.keys(NETWORKS),
    scheme:'exact', payloadEngine:'SF103_ORIGINAL_X402_STELLAR', feesSponsoredRequired:true };
}

/** Execute-only local setup check; does not read a wallet key, sign or call RPC. */
export async function checkNativeSignerPrerequisites(options) {
  pins(options);
  if (options.signerProvider !== undefined) {
    if (options.secretEnv !== undefined) fail('SIGNER_ONE_SOURCE_REQUIRED');
    await inspectSignerProvider(options.signerProvider);
  } else {
    const environment = options.environment ?? process.env;
    const secretEnv = options.secretEnv ?? 'STELLAR_SECRET';
    if (typeof secretEnv !== 'string' || !/^[A-Z][A-Z0-9_]{0,127}$/.test(secretEnv))
      fail('SIGNER_INVALID_SECRET_ENV_NAME');
    if (!object(environment) || !Object.hasOwn(environment, secretEnv))
      fail(options.network === NETWORK ? 'SIGNER_LOCAL_TESTNET_KEY_REQUIRED' : 'SIGNER_LOCAL_KEY_REQUIRED');
  }
  await officialSdk();
}

/**
 * Existing official ClientStellarSigner -> SF31 sign callback.
 * Call only from the operator-owned SF81 path after its durable reservation.
 * The SDK simulates/signs authorization; SF31 alone sends the paid HTTP retry.
 */
export async function createOfficialStellarSigner(options) {
  const policy = pins(options);
  const signer = options.signer;
  if (!object(signer) || signer.address !== policy.expectedPayer || typeof signer.signAuthEntry !== 'function')
    fail('SIGNER_PAYER_MISMATCH');
  const sdk = await officialSdk();
  const attemptedIntents = new Set();
  return Object.freeze({ payer: signer.address, network: policy.network,
    async sign(payload) {
      const input = validateNativeSignerInput(payload, policy);
      if (signer.address !== policy.expectedPayer) fail('SIGNER_PAYER_MISMATCH');
      if (attemptedIntents.has(input.intent.intentId)) fail('NATIVE_SIGNING_ALREADY_ATTEMPTED');
      attemptedIntents.add(input.intent.intentId);
      // SF88 retains its independent workspace policy; SF103 is the single
      // shared native payload engine. The existing SF31/SF81 call supplies the
      // approved request body and operation, after its durable reservation.
